                                                                                                                                                                                                                   pg_get_functiondef                                                                                                                                                                                                                   
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 CREATE OR REPLACE FUNCTION public.agregar_comparativo_nicho()                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS integer                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_inseridos int := 0;                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_nicho record;                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   v_count int;                                                                                                                                                                                                                                                                                                                                                                                                                                        +
   v_taxa_media numeric;                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_ticket_media numeric;                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_ruido numeric;                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_epsilon constant numeric := 0.1;                                                                                                                                                                                                                                                                                                                                                                                                                  +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   FOR v_nicho IN                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     SELECT p.nicho_id, count(*) AS n                                                                                                                                                                                                                                                                                                                                                                                                                  +
     FROM public.perfil_empresa pe                                                                                                                                                                                                                                                                                                                                                                                                                     +
     JOIN public.profiles p ON p.id = pe.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                     +
     WHERE p.nicho_id IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                      +
       AND pe.taxa_conversao_estimada IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                      +
     GROUP BY p.nicho_id                                                                                                                                                                                                                                                                                                                                                                                                                               +
     HAVING count(*) >= 10                                                                                                                                                                                                                                                                                                                                                                                                                             +
   LOOP                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     SELECT avg(pe.taxa_conversao_estimada), count(*)                                                                                                                                                                                                                                                                                                                                                                                                  +
     INTO v_taxa_media, v_count                                                                                                                                                                                                                                                                                                                                                                                                                        +
     FROM public.perfil_empresa pe                                                                                                                                                                                                                                                                                                                                                                                                                     +
     JOIN public.profiles p ON p.id = pe.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                     +
     WHERE p.nicho_id = v_nicho.nicho_id                                                                                                                                                                                                                                                                                                                                                                                                               +
       AND pe.taxa_conversao_estimada IS NOT NULL;                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     v_ruido := (random() * 2 - 1) * (1.0 / v_epsilon) * 0.01;                                                                                                                                                                                                                                                                                                                                                                                         +
     v_taxa_media := greatest(0, least(1, v_taxa_media + v_ruido));                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     INSERT INTO public.comparativo_nicho                                                                                                                                                                                                                                                                                                                                                                                                              +
       (nicho_id, metrica, valor_anonimizado, count_tenants, epsilon, janela_dias, expira_em)                                                                                                                                                                                                                                                                                                                                                          +
     VALUES                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       (v_nicho.nicho_id, 'taxa_conversao_media',                                                                                                                                                                                                                                                                                                                                                                                                      +
        jsonb_build_object('valor', round(v_taxa_media, 4), 'unidade', 'fracao'),                                                                                                                                                                                                                                                                                                                                                                      +
        v_count, v_epsilon, 30, now() + interval '7 days')                                                                                                                                                                                                                                                                                                                                                                                             +
     ON CONFLICT (nicho_id, metrica, janela_dias) DO UPDATE SET                                                                                                                                                                                                                                                                                                                                                                                        +
       valor_anonimizado = excluded.valor_anonimizado,                                                                                                                                                                                                                                                                                                                                                                                                 +
       count_tenants = excluded.count_tenants,                                                                                                                                                                                                                                                                                                                                                                                                         +
       epsilon = excluded.epsilon,                                                                                                                                                                                                                                                                                                                                                                                                                     +
       calculado_em = now(),                                                                                                                                                                                                                                                                                                                                                                                                                           +
       expira_em = now() + interval '7 days';                                                                                                                                                                                                                                                                                                                                                                                                          +
     v_inseridos := v_inseridos + 1;                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     SELECT avg(pe.ticket_medio_estimado)                                                                                                                                                                                                                                                                                                                                                                                                              +
     INTO v_ticket_media                                                                                                                                                                                                                                                                                                                                                                                                                               +
     FROM public.perfil_empresa pe                                                                                                                                                                                                                                                                                                                                                                                                                     +
     JOIN public.profiles p ON p.id = pe.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                     +
     WHERE p.nicho_id = v_nicho.nicho_id                                                                                                                                                                                                                                                                                                                                                                                                               +
       AND pe.ticket_medio_estimado IS NOT NULL;                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     IF v_ticket_media IS NOT NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                +
       INSERT INTO public.comparativo_nicho                                                                                                                                                                                                                                                                                                                                                                                                            +
         (nicho_id, metrica, valor_anonimizado, count_tenants, epsilon, janela_dias, expira_em)                                                                                                                                                                                                                                                                                                                                                        +
       VALUES                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         (v_nicho.nicho_id, 'ticket_medio',                                                                                                                                                                                                                                                                                                                                                                                                            +
          jsonb_build_object('valor', round((v_ticket_media + (random() * 2 - 1) * (50.0 / v_epsilon))::numeric, 2), 'unidade', 'BRL'),                                                                                                                                                                                                                                                                                                                +
          v_count, v_epsilon, 30, now() + interval '7 days')                                                                                                                                                                                                                                                                                                                                                                                           +
       ON CONFLICT (nicho_id, metrica, janela_dias) DO UPDATE SET                                                                                                                                                                                                                                                                                                                                                                                      +
         valor_anonimizado = excluded.valor_anonimizado,                                                                                                                                                                                                                                                                                                                                                                                               +
         count_tenants = excluded.count_tenants,                                                                                                                                                                                                                                                                                                                                                                                                       +
         epsilon = excluded.epsilon,                                                                                                                                                                                                                                                                                                                                                                                                                   +
         calculado_em = now(),                                                                                                                                                                                                                                                                                                                                                                                                                         +
         expira_em = now() + interval '7 days';                                                                                                                                                                                                                                                                                                                                                                                                        +
       v_inseridos := v_inseridos + 1;                                                                                                                                                                                                                                                                                                                                                                                                                 +
     END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   END LOOP;                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   RETURN v_inseridos;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.analisar_causa_efeito_tenant(p_tenant_id uuid)                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS TABLE(metrica text, ferramenta_ou_cargo text, n_amostras bigint, taxa_conversao_quando_usada numeric, taxa_conversao_geral numeric, diferenca_pp numeric)                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_taxa_geral numeric;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 CASE WHEN count(*) FILTER (WHERE desfecho IN ('convertido','perdido','sumiu')) > 0                                                                                                                                                                                                                                                                                                                                                                    +
 THEN count(*) FILTER (WHERE desfecho='convertido')::numeric                                                                                                                                                                                                                                                                                                                                                                                           +
 / count(*) FILTER (WHERE desfecho IN ('convertido','perdido','sumiu'))                                                                                                                                                                                                                                                                                                                                                                                +
 ELSE 0 END                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 INTO v_taxa_geral                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 FROM public.leads                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 WHERE tenant_id = p_tenant_id AND deleted_at IS NULL;                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 'desfecho'::text AS metrica,                                                                                                                                                                                                                                                                                                                                                                                                                          +
 coalesce(l.desfecho, 'sem_desfecho') AS ferramenta_ou_cargo,                                                                                                                                                                                                                                                                                                                                                                                          +
 count(*) AS n_amostras,                                                                                                                                                                                                                                                                                                                                                                                                                               +
 (count(*) FILTER (WHERE l.desfecho='convertido')::numeric / NULLIF(count(*), 0))::numeric(5,4) AS taxa_quando,                                                                                                                                                                                                                                                                                                                                        +
 v_taxa_geral::numeric(5,4) AS taxa_geral,                                                                                                                                                                                                                                                                                                                                                                                                             +
 ((count(*) FILTER (WHERE l.desfecho='convertido')::numeric / NULLIF(count(*), 0)) - v_taxa_geral)::numeric(5,4) AS diff                                                                                                                                                                                                                                                                                                                               +
 FROM public.leads l                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 WHERE l.tenant_id = p_tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AND l.deleted_at IS NULL                                                                                                                                                                                                                                                                                                                                                                                                                              +
 AND l.desfecho IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                            +
 GROUP BY l.desfecho                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 HAVING count(*) >= 5                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 ORDER BY diff DESC NULLS LAST;                                                                                                                                                                                                                                                                                                                                                                                                                        +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.aprovar_depoimento_para_rag(p_testimonial_id uuid, p_admin_id uuid)                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS uuid                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_testimonial public.depoimentos_publicos%ROWTYPE;                                                                                                                                                                                                                                                                                                                                                                                                  +
   v_chunk_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_conteudo text;                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_agente_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   SELECT * INTO v_testimonial FROM public.depoimentos_publicos WHERE id = p_testimonial_id;                                                                                                                                                                                                                                                                                                                                                           +
   IF NOT FOUND THEN RAISE EXCEPTION 'testimonial % não encontrado', p_testimonial_id USING ERRCODE = 'no_data_found'; END IF;                                                                                                                                                                                                                                                                                                                         +
   IF v_testimonial.user_id IS NULL THEN RAISE EXCEPTION 'testimonial sem user_id (tenant)' USING ERRCODE = 'invalid_parameter_value'; END IF;                                                                                                                                                                                                                                                                                                         +
   SELECT ua.id INTO v_agente_id FROM public.agentes_usuario ua WHERE ua.user_id = v_testimonial.user_id LIMIT 1;                                                                                                                                                                                                                                                                                                                                      +
   v_conteudo := format('Depoimento de %s (nota %s/5): %s', coalesce(v_testimonial.autor_nome, 'cliente anônimo'), coalesce(v_testimonial.nota::text, '-'), v_testimonial.texto);                                                                                                                                                                                                                                                                      +
   INSERT INTO public.blocos_conhecimento (agente_id, title, content, category, tipo, escopo, embedding_status, ativo, created_at, updated_at)                                                                                                                                                                                                                                                                                                         +
   VALUES (v_agente_id, 'Depoimento RAG', v_conteudo, 'social_proof', 'depoimento', 'tenant', 'pendente', true, now(), now())                                                                                                                                                                                                                                                                                                                          +
   RETURNING id INTO v_chunk_id;                                                                                                                                                                                                                                                                                                                                                                                                                       +
   UPDATE public.depoimentos_publicos SET aprovado = true, aprovado_at = now(), rag_bloco_id = v_chunk_id WHERE id = p_testimonial_id;                                                                                                                                                                                                                                                                                                                 +
   RETURN v_chunk_id;                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.aprovar_trecho_conversa_para_rag(p_tenant_id uuid, p_conversation_id uuid, p_message_ids uuid[], p_tipo text, p_categoria text, p_admin_id uuid, p_chunk_candidate_id uuid DEFAULT NULL::uuid)                                                                                                                                                                                                                      +
  RETURNS uuid                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_conteudo text;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 v_chunk_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 v_count int;                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 v_agente_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 PERFORM 1 FROM public.conversas WHERE id = p_conversation_id AND tenant_id = p_tenant_id;                                                                                                                                                                                                                                                                                                                                                             +
 IF NOT FOUND THEN RAISE EXCEPTION 'conversation % não pertence ao tenant %', p_conversation_id, p_tenant_id USING ERRCODE = 'insufficient_privilege'; END IF;                                                                                                                                                                                                                                                                                         +
 SELECT string_agg(m.role || ': ' || m.content, E'\n' ORDER BY m.created_at ASC), count(*)                                                                                                                                                                                                                                                                                                                                                             +
 INTO v_conteudo, v_count FROM public.mensagens m                                                                                                                                                                                                                                                                                                                                                                                                      +
 WHERE m.id = ANY(p_message_ids) AND m.conversation_id = p_conversation_id;                                                                                                                                                                                                                                                                                                                                                                            +
 IF v_count = 0 OR v_conteudo IS NULL THEN RAISE EXCEPTION 'nenhuma mensagem encontrada pra excerto' USING ERRCODE = 'no_data_found'; END IF;                                                                                                                                                                                                                                                                                                          +
 SELECT ua.id INTO v_agente_id FROM public.agentes_usuario ua WHERE ua.user_id = p_tenant_id LIMIT 1;                                                                                                                                                                                                                                                                                                                                                  +
 INSERT INTO public.blocos_conhecimento (agente_id, title, content, category, tipo, escopo, embedding_status, ativo, created_at, updated_at)                                                                                                                                                                                                                                                                                                           +
 VALUES (v_agente_id, 'Trecho Conversa RAG', v_conteudo, p_categoria, p_tipo, 'tenant', 'pendente', true, now(), now())                                                                                                                                                                                                                                                                                                                                +
 RETURNING id INTO v_chunk_id;                                                                                                                                                                                                                                                                                                                                                                                                                         +
 IF p_chunk_candidate_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                              +
 UPDATE public.candidatos_bloco SET status = 'promoted', promoted_bloco_id = v_chunk_id, promoted_bloco_table = 'blocos_conhecimento', decided_at = now(), decided_by = p_admin_id                                                                                                                                                                                                                                                                     +
 WHERE id = p_chunk_candidate_id AND tenant_id = p_tenant_id;                                                                                                                                                                                                                                                                                                                                                                                          +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 RETURN v_chunk_id;                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.busca_hibrida_emocao(p_query_text text, p_query_embedding halfvec, p_tenant_id uuid DEFAULT NULL::uuid, p_nicho_id uuid DEFAULT NULL::uuid, p_top_k integer DEFAULT 3, p_threshold numeric DEFAULT 0.35, p_intensidade_min numeric DEFAULT 0.0, p_rrf_k integer DEFAULT 50)                                                                                                                                         +
  RETURNS TABLE(id uuid, emocao text, corpo text, intensidade_match numeric, escopo text, prioridade integer, score numeric)                                                                                                                                                                                                                                                                                                                           +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                              +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                        +
   WITH semantica AS (                                                                                                                                                                                                                                                                                                                                                                                                                                 +
     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       e.id, e.emocao, e.corpo, e.intensidade_match, e.escopo, e.prioridade,                                                                                                                                                                                                                                                                                                                                                                           +
       (1 - (e.vetor_semantico OPERATOR(extensions.<=>) p_query_embedding)::numeric) AS sim,                                                                                                                                                                                                                                                                                                                                                           +
       ROW_NUMBER() OVER (ORDER BY (e.vetor_semantico OPERATOR(extensions.<=>) p_query_embedding) ASC) AS rank_sem                                                                                                                                                                                                                                                                                                                                     +
     FROM public.emocao_blocos e                                                                                                                                                                                                                                                                                                                                                                                                                       +
     WHERE e.ativo = true                                                                                                                                                                                                                                                                                                                                                                                                                              +
       AND e.embedding_status = 'pronto'                                                                                                                                                                                                                                                                                                                                                                                                               +
       AND e.intensidade_match >= p_intensidade_min                                                                                                                                                                                                                                                                                                                                                                                                    +
       AND (                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         e.escopo = 'global'                                                                                                                                                                                                                                                                                                                                                                                                                           +
         OR (e.escopo = 'nicho' AND p_nicho_id IS NOT NULL AND e.nicho_id = p_nicho_id)                                                                                                                                                                                                                                                                                                                                                                +
         OR (e.escopo = 'tenant' AND p_tenant_id IS NOT NULL AND e.tenant_id = p_tenant_id)                                                                                                                                                                                                                                                                                                                                                            +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       AND NOT (                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         e.escopo = 'nicho' AND p_tenant_id IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                +
         AND EXISTS (SELECT 1 FROM public.overrides_tenant_blocos_emocao ov                                                                                                                                                                                                                                                                                                                                                                            +
                     WHERE ov.bloco_id = e.id AND ov.tenant_id = p_tenant_id AND ov.ativo = false)                                                                                                                                                                                                                                                                                                                                                     +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     ORDER BY e.vetor_semantico OPERATOR(extensions.<=>) p_query_embedding                                                                                                                                                                                                                                                                                                                                                                             +
     LIMIT 50                                                                                                                                                                                                                                                                                                                                                                                                                                          +
   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   lexica AS (                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       e.id,                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       ROW_NUMBER() OVER (ORDER BY ts_rank_cd(to_tsvector('portuguese', coalesce(e.corpo,'') || ' ' || coalesce(e.emocao,'')),                                                                                                                                                                                                                                                                                                                         +
                                               plainto_tsquery('portuguese', p_query_text)) DESC) AS rank_lex                                                                                                                                                                                                                                                                                                                                          +
     FROM public.emocao_blocos e                                                                                                                                                                                                                                                                                                                                                                                                                       +
     WHERE e.ativo = true                                                                                                                                                                                                                                                                                                                                                                                                                              +
       AND to_tsvector('portuguese', coalesce(e.corpo,'') || ' ' || coalesce(e.emocao,'')) @@ plainto_tsquery('portuguese', p_query_text)                                                                                                                                                                                                                                                                                                              +
       AND (                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         e.escopo = 'global'                                                                                                                                                                                                                                                                                                                                                                                                                           +
         OR (e.escopo = 'nicho' AND p_nicho_id IS NOT NULL AND e.nicho_id = p_nicho_id)                                                                                                                                                                                                                                                                                                                                                                +
         OR (e.escopo = 'tenant' AND p_tenant_id IS NOT NULL AND e.tenant_id = p_tenant_id)                                                                                                                                                                                                                                                                                                                                                            +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       AND NOT (                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         e.escopo = 'nicho' AND p_tenant_id IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                +
         AND EXISTS (SELECT 1 FROM public.overrides_tenant_blocos_emocao ov                                                                                                                                                                                                                                                                                                                                                                            +
                     WHERE ov.bloco_id = e.id AND ov.tenant_id = p_tenant_id AND ov.ativo = false)                                                                                                                                                                                                                                                                                                                                                     +
       )                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     LIMIT 50                                                                                                                                                                                                                                                                                                                                                                                                                                          +
   )                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     s.id, s.emocao, s.corpo, s.intensidade_match, s.escopo, s.prioridade,                                                                                                                                                                                                                                                                                                                                                                             +
     (1.0/(p_rrf_k + s.rank_sem) + COALESCE(1.0/(p_rrf_k + l.rank_lex), 0.0))::numeric AS score                                                                                                                                                                                                                                                                                                                                                        +
   FROM semantica s                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   LEFT JOIN lexica l ON l.id = s.id                                                                                                                                                                                                                                                                                                                                                                                                                   +
   WHERE s.sim >= p_threshold                                                                                                                                                                                                                                                                                                                                                                                                                          +
   ORDER BY score DESC                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   LIMIT p_top_k;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.busca_vetorial(query_embedding vector, p_agent_id uuid, match_count integer DEFAULT 8, similarity_threshold double precision DEFAULT 0.45, p_exclude_categories text[] DEFAULT ARRAY['fluxo'::text])                                                                                                                                                                                                                +
  RETURNS TABLE(id uuid, title text, content text, category text, tags text[], similarity double precision)                                                                                                                                                                                                                                                                                                                                            +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT kc.id, kc.title, kc.content, kc.category, kc.tags, 1 - (kc.vetor_semantico OPERATOR(extensions.<=>) query_embedding) AS similarity                                                                                                                                                                                                                                                                                                             +
 FROM public.blocos_conhecimento kc                                                                                                                                                                                                                                                                                                                                                                                                                    +
 WHERE kc.agente_id = p_agent_id AND kc.vetor_semantico IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                    +
 AND (p_exclude_categories IS NULL OR kc.category IS NULL OR kc.category <> ALL(p_exclude_categories))                                                                                                                                                                                                                                                                                                                                                 +
 AND 1 - (kc.vetor_semantico OPERATOR(extensions.<=>) query_embedding) >= similarity_threshold                                                                                                                                                                                                                                                                                                                                                         +
 ORDER BY kc.vetor_semantico OPERATOR(extensions.<=>) query_embedding LIMIT match_count;                                                                                                                                                                                                                                                                                                                                                               +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.buscar_pergunta_similar(p_tenant_id uuid, p_embedding halfvec, p_limiar double precision DEFAULT 0.88)                                                                                                                                                                                                                                                                                                              +
  RETURNS TABLE(id uuid, pergunta text, resposta_do_dono text, status_loop text, ocorrencias integer, bloco_criado_id uuid, similaridade double precision)                                                                                                                                                                                                                                                                                             +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   SELECT ps.id, ps.pergunta, ps.resposta_do_dono, ps.status_loop, ps.ocorrencias,                                                                                                                                                                                                                                                                                                                                                                     +
          ps.bloco_criado_id,                                                                                                                                                                                                                                                                                                                                                                                                                          +
          1 - (ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding) AS similaridade                                                                                                                                                                                                                                                                                                                                                                +
   FROM public.perguntas_sem_resposta ps                                                                                                                                                                                                                                                                                                                                                                                                               +
   WHERE ps.tenant_id = p_tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                    +
     AND ps.vetor_semantico IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                +
     AND (ps.status_loop = 'aguardando_dono' OR ps.resposta_do_dono IS NOT NULL)                                                                                                                                                                                                                                                                                                                                                                       +
     AND 1 - (ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding) >= p_limiar                                                                                                                                                                                                                                                                                                                                                                     +
   ORDER BY ps.vetor_semantico OPERATOR(extensions.<=>) p_embedding                                                                                                                                                                                                                                                                                                                                                                                    +
   LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.criar_cliente_manual(p_name text, p_phone text, p_product text DEFAULT NULL::text, p_email text DEFAULT NULL::text)                                                                                                                                                                                                                                                                                                 +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_user_id uuid; v_agent_id uuid; v_lead_id uuid; v_conv_id uuid; v_token uuid; v_existing_lead_id uuid;                                                                                                                                                                                                                                                                                                                                               +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 SELECT COALESCE(p.parent_user_id, p.id) INTO v_user_id FROM public.profiles p WHERE p.id = (SELECT auth.uid());                                                                                                                                                                                                                                                                                                                                       +
 IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF;                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT l.id INTO v_existing_lead_id FROM public.leads l WHERE l.tenant_id = v_user_id AND l.phone = p_phone LIMIT 1;                                                                                                                                                                                                                                                                                                                                  +
 IF v_existing_lead_id IS NOT NULL THEN RAISE EXCEPTION 'Já existe um lead com este telefone'; END IF;                                                                                                                                                                                                                                                                                                                                                 +
 SELECT ua.id INTO v_agent_id FROM public.agentes_usuario ua WHERE ua.user_id = v_user_id LIMIT 1;                                                                                                                                                                                                                                                                                                                                                     +
 v_token := gen_random_uuid();                                                                                                                                                                                                                                                                                                                                                                                                                         +
 INSERT INTO public.leads (tenant_id, name, nome_exibicao, phone, email, produto, fase_pipeline, fase_cliente, converted_at, chave_rastreamento, origem_lead, temperatura_lead)                                                                                                                                                                                                                                                                        +
 VALUES (v_user_id, p_name, p_name, p_phone, p_email, COALESCE(p_product, ''), 'fechado', 'documentacao', now(), v_token, 'manual', 'quente') RETURNING id INTO v_lead_id;                                                                                                                                                                                                                                                                             +
 INSERT INTO public.conversas (tenant_id, lead_id, phone, channel, status, agent_enabled)                                                                                                                                                                                                                                                                                                                                                              +
 VALUES (v_user_id, v_lead_id, p_phone, 'whatsapp', 'ativa', true) RETURNING id INTO v_conv_id;                                                                                                                                                                                                                                                                                                                                                        +
 IF v_agent_id IS NOT NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                        +
 INSERT INTO public.fichas_lead (conversation_id, lead_id, agente_id, ciclo, fase) VALUES (v_conv_id, v_lead_id, v_agent_id, 1, 'fechado');                                                                                                                                                                                                                                                                                                            +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 RETURN jsonb_build_object('lead_id', v_lead_id, 'conversation_id', v_conv_id, 'tracking_token', v_token);                                                                                                                                                                                                                                                                                                                                             +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.detectar_intent_categoria(p_query_embedding halfvec, p_top_k integer DEFAULT 2)                                                                                                                                                                                                                                                                                                                                     +
  RETURNS TABLE(intent text, frase_pivo text, categorias_alvo text[], similaridade numeric)                                                                                                                                                                                                                                                                                                                                                            +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 p.intent,                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 p.frase_pivo,                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 p.categorias_alvo,                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 (1 - (p.vetor_semantico OPERATOR(extensions.<=>) p_query_embedding))::numeric AS similaridade                                                                                                                                                                                                                                                                                                                                                         +
 FROM public.pivots_categoria_intent p                                                                                                                                                                                                                                                                                                                                                                                                                 +
 WHERE p.ativo = true                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 AND p.vetor_semantico IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                     +
 AND p.embedding_status = 'ready'                                                                                                                                                                                                                                                                                                                                                                                                                      +
 ORDER BY p.vetor_semantico OPERATOR(extensions.<=>) p_query_embedding                                                                                                                                                                                                                                                                                                                                                                                 +
 LIMIT p_top_k;                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.enviar_reproposta(p_campaign_lead_ids uuid[], p_texto text DEFAULT NULL::text)                                                                                                                                                                                                                                                                                                                                      +
  RETURNS TABLE(campaign_lead_id uuid, reproposta_id uuid, scheduled_action_id uuid, status text)                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_caller uuid := auth.uid(); v_rec record; v_actid uuid; v_conv uuid; v_agent uuid; v_idx integer := 0;                                                                                                                                                                                                                                                                                                                                               +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;                                                                                                                                                                                                                                                                                                                                                                                   +
 FOR v_rec IN                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT cl.id AS cl_id, cl.lead_id AS lead_id, cl.campaign_id AS campaign_id, cl.reproposta_count AS rep_count,                                                                                                                                                                                                                                                                                                                                        +
 c.tenant_id AS tenant_id, c.status AS campaign_status, c.deleted_at AS campaign_deleted_at                                                                                                                                                                                                                                                                                                                                                            +
 FROM public.leads_campanha cl JOIN public.campanhas c ON c.id = cl.campaign_id                                                                                                                                                                                                                                                                                                                                                                        +
 WHERE cl.id = ANY(p_campaign_lead_ids)                                                                                                                                                                                                                                                                                                                                                                                                                +
 AND (c.tenant_id = v_caller                                                                                                                                                                                                                                                                                                                                                                                                                           +
 OR c.tenant_id IN (SELECT p.parent_user_id FROM public.profiles p WHERE p.id = v_caller AND p.parent_user_id IS NOT NULL)                                                                                                                                                                                                                                                                                                                             +
 OR public.is_platform_admin())                                                                                                                                                                                                                                                                                                                                                                                                                        +
 LOOP                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 IF v_rec.campaign_deleted_at IS NOT NULL OR v_rec.campaign_status NOT IN ('active','paused','ativa','pausada') THEN                                                                                                                                                                                                                                                                                                                                   +
 campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'campanha_inativa';                                                                                                                                                                                                                                                                                                                                    +
 RETURN NEXT; CONTINUE;                                                                                                                                                                                                                                                                                                                                                                                                                                +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 IF v_rec.rep_count >= 10 THEN                                                                                                                                                                                                                                                                                                                                                                                                                         +
 campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'throttle_atingido';                                                                                                                                                                                                                                                                                                                                   +
 RETURN NEXT; CONTINUE;                                                                                                                                                                                                                                                                                                                                                                                                                                +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 IF EXISTS (SELECT 1 FROM public.exclusoes_tenant toov WHERE toov.tenant_id = v_rec.tenant_id AND toov.lead_id = v_rec.lead_id) THEN                                                                                                                                                                                                                                                                                                                   +
 campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'opt_out';                                                                                                                                                                                                                                                                                                                                             +
 RETURN NEXT; CONTINUE;                                                                                                                                                                                                                                                                                                                                                                                                                                +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 IF EXISTS (SELECT 1 FROM public.leads l WHERE l.id = v_rec.lead_id AND l.opt_out_at IS NOT NULL) THEN                                                                                                                                                                                                                                                                                                                                                 +
 campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := NULL; status := 'opt_out_lead';                                                                                                                                                                                                                                                                                                                                        +
 RETURN NEXT; CONTINUE;                                                                                                                                                                                                                                                                                                                                                                                                                                +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 UPDATE public.acoes_agendadas SET status = 'cancelado'                                                                                                                                                                                                                                                                                                                                                                                                +
 WHERE lead_id = v_rec.lead_id AND acoes_agendadas.status IN ('pending','pendente')                                                                                                                                                                                                                                                                                                                                                                    +
 AND action_type IN ('campaign_trigger','campaign_reproposta','retomada_encerramento');                                                                                                                                                                                                                                                                                                                                                                +
 v_idx := v_idx + 1;                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 SELECT co.id, co.agente_id INTO v_conv, v_agent FROM public.conversas co                                                                                                                                                                                                                                                                                                                                                                              +
 WHERE co.lead_id = v_rec.lead_id AND co.tenant_id = v_rec.tenant_id ORDER BY co.updated_at DESC NULLS LAST LIMIT 1;                                                                                                                                                                                                                                                                                                                                   +
 INSERT INTO public.acoes_agendadas (lead_id, conversation_id, agente_id, action_type, scheduled_at, status, carga)                                                                                                                                                                                                                                                                                                                                    +
 VALUES (v_rec.lead_id, v_conv, v_agent, 'campaign_reproposta', now() + ((v_idx - 1) * interval '1 minute'), 'pendente',                                                                                                                                                                                                                                                                                                                               +
 jsonb_build_object('campaign_id', v_rec.campaign_id, 'campaign_lead_id', v_rec.cl_id, 'texto_personalizado', COALESCE(p_texto,'')))                                                                                                                                                                                                                                                                                                                   +
 RETURNING id INTO v_actid;                                                                                                                                                                                                                                                                                                                                                                                                                            +
 UPDATE public.leads_campanha SET reproposta_count = reproposta_count + 1 WHERE id = v_rec.cl_id;                                                                                                                                                                                                                                                                                                                                                      +
 campaign_lead_id := v_rec.cl_id; reproposta_id := NULL; scheduled_action_id := v_actid; status := 'enfileirada';                                                                                                                                                                                                                                                                                                                                      +
 RETURN NEXT;                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 END LOOP;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 RETURN;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.exportar_meus_dados()                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_user_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 v_result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 v_user_id := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                              +
 IF v_user_id IS NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                             +
 RAISE EXCEPTION 'Não autenticado';                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 INSERT INTO public.activity_logs (user_id, action, entity_type, metadata)                                                                                                                                                                                                                                                                                                                                                                             +
 VALUES (v_user_id, 'lgpd_export', 'user', '{}'::jsonb);                                                                                                                                                                                                                                                                                                                                                                                               +
 SELECT jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                            +
 'profile', (SELECT row_to_json(p) FROM public.profiles p WHERE id = v_user_id),                                                                                                                                                                                                                                                                                                                                                                       +
 'conversas', (SELECT json_agg(row_to_json(c)) FROM public.conversas c WHERE lead_id IN (SELECT id FROM public.leads WHERE tenant_id = (SELECT tenant_id FROM public.profiles WHERE id = v_user_id))),                                                                                                                                                                                                                                                 +
 'leads', (SELECT json_agg(row_to_json(l)) FROM public.leads l WHERE tenant_id = (SELECT tenant_id FROM public.profiles WHERE id = v_user_id)),                                                                                                                                                                                                                                                                                                        +
 'contratos', (SELECT json_agg(row_to_json(ct)) FROM public.contratos ct WHERE lead_id IN (SELECT id FROM public.leads WHERE tenant_id = (SELECT tenant_id FROM public.profiles WHERE id = v_user_id))),                                                                                                                                                                                                                                               +
 'activity_logs', (SELECT json_agg(row_to_json(a)) FROM public.activity_logs a WHERE user_id = v_user_id)                                                                                                                                                                                                                                                                                                                                              +
 ) INTO v_result;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 RETURN COALESCE(v_result, '{}'::jsonb);                                                                                                                                                                                                                                                                                                                                                                                                               +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.fn_saude_motor()                                                                                                                                                                                                                                                                                                                                                                                                    +
  RETURNS TABLE(fila text, pendentes bigint, ultimo_evento timestamp with time zone)                                                                                                                                                                                                                                                                                                                                                                   +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public', 'pgmq'                                                                                                                                                                                                                                                                                                                                                                                                                  +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 q.queue_name::text,                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 coalesce(m.queue_length, 0)::bigint,                                                                                                                                                                                                                                                                                                                                                                                                                  +
 CASE WHEN m.newest_msg_age_sec IS NOT NULL AND m.newest_msg_age_sec > 0                                                                                                                                                                                                                                                                                                                                                                               +
 THEN now() - (m.newest_msg_age_sec || ' seconds')::interval                                                                                                                                                                                                                                                                                                                                                                                           +
 ELSE NULL END AS ultimo_evento                                                                                                                                                                                                                                                                                                                                                                                                                        +
 FROM pgmq.list_queues() q                                                                                                                                                                                                                                                                                                                                                                                                                             +
 LEFT JOIN LATERAL (SELECT * FROM pgmq.metrics(q.queue_name)) m ON true                                                                                                                                                                                                                                                                                                                                                                                +
 WHERE q.queue_name LIKE 'fila_%';                                                                                                                                                                                                                                                                                                                                                                                                                     +
 EXCEPTION WHEN OTHERS THEN RETURN;                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.gerar_sugestoes_fusao_tag(p_nicho_id uuid, p_threshold numeric DEFAULT 0.85, p_min_leads integer DEFAULT 1)                                                                                                                                                                                                                                                                                                         +
  RETURNS integer                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public', 'extensions'                                                                                                                                                                                                                                                                                                                                                                                                            +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE v_count integer := 0;                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 IF p_nicho_id IS NULL THEN RAISE EXCEPTION 'nicho_id obrigatorio'; END IF;                                                                                                                                                                                                                                                                                                                                                                            +
 DELETE FROM public.sugestoes_fusao_tag WHERE nicho_id = p_nicho_id AND status IN ('pending','pendente');                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH RECURSIVE                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 pares AS (                                                                                                                                                                                                                                                                                                                                                                                                                                            +
   SELECT a.tag_text AS tag_a, b.tag_text AS tag_b,                                                                                                                                                                                                                                                                                                                                                                                                    +
          1 - (a.vetor_semantico OPERATOR(extensions.<=>) b.vetor_semantico) AS sim                                                                                                                                                                                                                                                                                                                                                                    +
   FROM public.candidatos_tag a                                                                                                                                                                                                                                                                                                                                                                                                                        +
   JOIN public.candidatos_tag b ON a.nicho_id = b.nicho_id AND a.tag_text < b.tag_text                                                                                                                                                                                                                                                                                                                                                                 +
   WHERE a.nicho_id = p_nicho_id                                                                                                                                                                                                                                                                                                                                                                                                                       +
     AND a.vetor_semantico IS NOT NULL AND b.vetor_semantico IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                               +
     AND a.num_leads_independentes >= p_min_leads                                                                                                                                                                                                                                                                                                                                                                                                      +
     AND b.num_leads_independentes >= p_min_leads                                                                                                                                                                                                                                                                                                                                                                                                      +
     AND 1 - (a.vetor_semantico OPERATOR(extensions.<=>) b.vetor_semantico) >= p_threshold                                                                                                                                                                                                                                                                                                                                                             +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 vertices AS (                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   SELECT DISTINCT tag_a AS tag FROM pares UNION SELECT DISTINCT tag_b FROM pares                                                                                                                                                                                                                                                                                                                                                                      +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 arestas_bid AS (                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   SELECT tag_a AS a, tag_b AS b FROM pares                                                                                                                                                                                                                                                                                                                                                                                                            +
   UNION ALL SELECT tag_b, tag_a FROM pares                                                                                                                                                                                                                                                                                                                                                                                                            +
   UNION ALL SELECT tag, tag FROM vertices                                                                                                                                                                                                                                                                                                                                                                                                             +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 alcanc AS (                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   SELECT tag AS origem, tag AS atual FROM vertices                                                                                                                                                                                                                                                                                                                                                                                                    +
   UNION ALL                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   SELECT al.origem, e.b FROM alcanc al JOIN arestas_bid e ON e.a = al.atual                                                                                                                                                                                                                                                                                                                                                                           +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 componentes AS (                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   SELECT origem AS tag, MIN(atual) AS root FROM alcanc GROUP BY origem                                                                                                                                                                                                                                                                                                                                                                                +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 clusters AS (                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   SELECT c.root,                                                                                                                                                                                                                                                                                                                                                                                                                                      +
          array_agg(DISTINCT c.tag ORDER BY c.tag) AS cluster_tags,                                                                                                                                                                                                                                                                                                                                                                                    +
          (SELECT tc.tag_text FROM public.candidatos_tag tc                                                                                                                                                                                                                                                                                                                                                                                            +
           WHERE tc.nicho_id = p_nicho_id AND tc.tag_text = ANY(array_agg(DISTINCT c.tag))                                                                                                                                                                                                                                                                                                                                                             +
           ORDER BY tc.num_leads_independentes DESC, tc.criado_em ASC LIMIT 1) AS canonical,                                                                                                                                                                                                                                                                                                                                                           +
          (SELECT MAX(tc.num_leads_independentes) FROM public.candidatos_tag tc                                                                                                                                                                                                                                                                                                                                                                        +
           WHERE tc.nicho_id = p_nicho_id AND tc.tag_text = ANY(array_agg(DISTINCT c.tag))) AS max_leads,                                                                                                                                                                                                                                                                                                                                              +
          (SELECT COALESCE(AVG(p.sim), 0) FROM pares p                                                                                                                                                                                                                                                                                                                                                                                                 +
           WHERE p.tag_a = ANY(array_agg(DISTINCT c.tag)) AND p.tag_b = ANY(array_agg(DISTINCT c.tag))) AS avg_sim                                                                                                                                                                                                                                                                                                                                     +
   FROM componentes c                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   GROUP BY c.root                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   HAVING count(DISTINCT c.tag) >= 2                                                                                                                                                                                                                                                                                                                                                                                                                   +
 )                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 INSERT INTO public.sugestoes_fusao_tag (nicho_id, tags, suggested_canonical, similarity, status, motivo, criado_em, tag_a, tag_b)                                                                                                                                                                                                                                                                                                                     +
 SELECT p_nicho_id, cluster_tags, canonical, avg_sim, 'pendente',                                                                                                                                                                                                                                                                                                                                                                                      +
        format('cluster=%s tags leads_canonica=%s', array_length(cluster_tags, 1), max_leads),                                                                                                                                                                                                                                                                                                                                                         +
        now(), cluster_tags[1],                                                                                                                                                                                                                                                                                                                                                                                                                        +
        CASE WHEN array_length(cluster_tags, 1) >= 2 THEN cluster_tags[2] ELSE cluster_tags[1] END                                                                                                                                                                                                                                                                                                                                                     +
 FROM clusters;                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 GET DIAGNOSTICS v_count = ROW_COUNT;                                                                                                                                                                                                                                                                                                                                                                                                                  +
 RETURN v_count;                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.gestao_eliminar_expirados(p_executar boolean DEFAULT false)                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS TABLE(tabela text, linhas bigint)                                                                                                                                                                                                                                                                                                                                                                                                            +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 declare v_anos integer; v_corte timestamptz; n bigint;                                                                                                                                                                                                                                                                                                                                                                                                +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 if not public.gestao_eh_admin() then raise exception 'gestao: so o admin elimina dados expirados' using errcode = '42501'; end if;                                                                                                                                                                                                                                                                                                                    +
 select case when (valor ->> 'anos') ~ '^[0-9]{1,2}$' then (valor ->> 'anos')::integer end into v_anos from public.gestao_config where chave = 'retencao' and deleted_at is null;                                                                                                                                                                                                                                                                      +
 v_anos := coalesce(v_anos, 5);                                                                                                                                                                                                                                                                                                                                                                                                                        +
 if v_anos < 1 then raise exception 'gestao: retencao invalida' using errcode = '22023'; end if;                                                                                                                                                                                                                                                                                                                                                       +
 v_corte := now() - make_interval(years => v_anos);                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 tabela := 'gestao_vendas';                                                                                                                                                                                                                                                                                                                                                                                                                            +
 if p_executar then                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   delete from public.gestao_vendas where criado_em < v_corte;                                                                                                                                                                                                                                                                                                                                                                                         +
   get diagnostics n = row_count;                                                                                                                                                                                                                                                                                                                                                                                                                      +
 else                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   select count(*) into n from public.gestao_vendas where criado_em < v_corte;                                                                                                                                                                                                                                                                                                                                                                         +
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 linhas := n; return next;                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 tabela := 'gestao_indicacoes';                                                                                                                                                                                                                                                                                                                                                                                                                        +
 if p_executar then                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   delete from public.gestao_indicacoes where criado_em < v_corte;                                                                                                                                                                                                                                                                                                                                                                                     +
   get diagnostics n = row_count;                                                                                                                                                                                                                                                                                                                                                                                                                      +
 else                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   select count(*) into n from public.gestao_indicacoes where criado_em < v_corte;                                                                                                                                                                                                                                                                                                                                                                     +
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 linhas := n; return next;                                                                                                                                                                                                                                                                                                                                                                                                                             +
 end                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.get_indicador_publico(p_token uuid)                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS TABLE(campaign_id uuid, tenant_id uuid, cupom text, chave_publica uuid, indicador_nome text, indicador_email text, indicador_telefone text, indicador_foto_url text, comissao_tipo text, comissao_valor numeric, pagamento_valor numeric, pagamento_data date, pagamento_metodo text, comprovante_url text, observacao text, concluida_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)+
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT m.campaign_id, m.tenant_id, m.cupom, m.chave_publica, m.indicador_nome, m.indicador_email, m.indicador_telefone, m.indicador_foto_url, m.comissao_tipo, m.comissao_valor, m.pagamento_valor, m.pagamento_data, m.pagamento_metodo, m.comprovante_url, m.observacao, m.concluida_at, m.created_at, m.updated_at                                                                                                                                 +
 FROM public.meta_indicacao_campanha m                                                                                                                                                                                                                                                                                                                                                                                                                 +
 WHERE m.chave_publica = p_token                                                                                                                                                                                                                                                                                                                                                                                                                       +
 LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.integracao_provisionar_conta(p_user_id uuid, p_nicho_id uuid, p_dados jsonb DEFAULT '{}'::jsonb)                                                                                                                                                                                                                                                                                                                    +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 tmpl record;                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 novo_produto_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 _dias int := coalesce(nullif(p_dados->>'dias_degustacao','')::int, 7);                                                                                                                                                                                                                                                                                                                                                                                +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 if p_user_id is null then raise exception 'p_user_id obrigatório'; end if;                                                                                                                                                                                                                                                                                                                                                                            +
 update public.profiles set                                                                                                                                                                                                                                                                                                                                                                                                                            +
 nicho_id = coalesce(p_nicho_id, nicho_id),                                                                                                                                                                                                                                                                                                                                                                                                            +
 phone = coalesce(nullif(p_dados->>'phone',''), phone),                                                                                                                                                                                                                                                                                                                                                                                                +
 document = coalesce(nullif(p_dados->>'document',''), document),                                                                                                                                                                                                                                                                                                                                                                                       +
 tipo_pessoa = coalesce(nullif(p_dados->>'tipo_pessoa',''), tipo_pessoa),                                                                                                                                                                                                                                                                                                                                                                              +
 cnpj = coalesce(nullif(p_dados->>'cnpj',''), cnpj),                                                                                                                                                                                                                                                                                                                                                                                                   +
 razao_social = coalesce(nullif(p_dados->>'razao_social',''), razao_social),                                                                                                                                                                                                                                                                                                                                                                           +
 account_status = 'pendente',                                                                                                                                                                                                                                                                                                                                                                                                                          +
 metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('origem', 'babel-central', 'degustacao_ate', (now() + make_interval(days => _dias))::text)                                                                                                                                                                                                                                                                                            +
 where id = p_user_id;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 if not found then raise exception 'profile % não existe', p_user_id; end if;                                                                                                                                                                                                                                                                                                                                                                          +
 if p_nicho_id is not null then                                                                                                                                                                                                                                                                                                                                                                                                                        +
 for tmpl in select * from public.produto_templates where nicho_id = p_nicho_id and ativo = true loop                                                                                                                                                                                                                                                                                                                                                  +
 insert into public.produtos (user_id, nome, prazo_entrega, garantia)                                                                                                                                                                                                                                                                                                                                                                                  +
 values (p_user_id, tmpl.nome, tmpl.prazo_entrega, tmpl.garantia)                                                                                                                                                                                                                                                                                                                                                                                      +
 returning id into novo_produto_id;                                                                                                                                                                                                                                                                                                                                                                                                                    +
 end loop;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 return jsonb_build_object('ok', true, 'user_id', p_user_id, 'dias_degustacao', _dias);                                                                                                                                                                                                                                                                                                                                                                +
 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.metricas_base(p_tenant_id uuid)                                                                                                                                                                                                                                                                                                                                                                                     +
  RETURNS TABLE(metrica text, valor jsonb)                                                                                                                                                                                                                                                                                                                                                                                                             +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                              +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT 'produto_mais_frequente'::text, jsonb_build_object('produto', produto, 'count', cnt)                                                                                                                                                                                                                                                                                                                                                           +
 FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 SELECT produto, COUNT(*) as cnt                                                                                                                                                                                                                                                                                                                                                                                                                       +
 FROM public.leads                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 WHERE tenant_id = p_tenant_id AND location = 'base' AND deleted_at IS NULL AND produto IS NOT NULL                                                                                                                                                                                                                                                                                                                                                    +
 GROUP BY produto ORDER BY cnt DESC LIMIT 1                                                                                                                                                                                                                                                                                                                                                                                                            +
 ) sub;                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.monitor_saude_motor()                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_alertas jsonb := '[]'::jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                       +
 v_motor_parado jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 v_leads_sem_resposta jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                           +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 PERFORM set_config('statement_timeout', '10s', true);                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH ultimas AS (                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 c.id AS conversation_id,                                                                                                                                                                                                                                                                                                                                                                                                                              +
 c.tenant_id,                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 c.agente_id,                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 c.status,                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 c.agent_enabled,                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 MAX(m.created_at) FILTER (WHERE m.role = 'user') AS ultima_user,                                                                                                                                                                                                                                                                                                                                                                                      +
 MAX(m.created_at) FILTER (WHERE m.role IN ('assistant','human')) AS ultima_agente,                                                                                                                                                                                                                                                                                                                                                                    +
 COUNT(*) FILTER (WHERE m.role = 'user' AND m.created_at > now() - interval '48 hours') AS msgs_lead_48h,                                                                                                                                                                                                                                                                                                                                              +
 COUNT(*) FILTER (WHERE m.role IN ('assistant','human') AND m.created_at > now() - interval '48 hours') AS msgs_agente_48h                                                                                                                                                                                                                                                                                                                             +
 FROM public.mensagens m                                                                                                                                                                                                                                                                                                                                                                                                                               +
 JOIN public.conversas c ON c.id = m.conversation_id                                                                                                                                                                                                                                                                                                                                                                                                   +
 WHERE c.status IN ('ativa', 'humano')                                                                                                                                                                                                                                                                                                                                                                                                                 +
 AND c.agent_enabled IS NOT FALSE                                                                                                                                                                                                                                                                                                                                                                                                                      +
 AND m.deleted_at IS NULL                                                                                                                                                                                                                                                                                                                                                                                                                              +
 AND m.created_at > now() - interval '48 hours'                                                                                                                                                                                                                                                                                                                                                                                                        +
 GROUP BY c.id, c.tenant_id, c.agente_id, c.status, c.agent_enabled                                                                                                                                                                                                                                                                                                                                                                                    +
 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 motor_parado AS (                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 conversation_id, tenant_id, agente_id, ultima_user, ultima_agente,                                                                                                                                                                                                                                                                                                                                                                                    +
 EXTRACT(EPOCH FROM (now() - ultima_user))/60 AS min_sem_resposta                                                                                                                                                                                                                                                                                                                                                                                      +
 FROM ultimas                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 WHERE ultima_user > COALESCE(ultima_agente, '1970-01-01'::timestamptz)                                                                                                                                                                                                                                                                                                                                                                                +
 AND ultima_user < now() - interval '30 minutes'                                                                                                                                                                                                                                                                                                                                                                                                       +
 AND msgs_lead_48h > 0                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 )                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.min_sem_resposta DESC), '[]'::jsonb)                                                                                                                                                                                                                                                                                                                                                                 +
 INTO v_motor_parado                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 FROM motor_parado m                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 WHERE m.min_sem_resposta > 30                                                                                                                                                                                                                                                                                                                                                                                                                         +
 LIMIT 50;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 IF jsonb_array_length(v_motor_parado) > 0 THEN                                                                                                                                                                                                                                                                                                                                                                                                        +
 v_alertas := v_alertas || jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                         +
 'tipo', 'motor_parado', 'severity', 'vermelho',                                                                                                                                                                                                                                                                                                                                                                                                       +
 'count', jsonb_array_length(v_motor_parado), 'detalhes', v_motor_parado                                                                                                                                                                                                                                                                                                                                                                               +
 );                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH sem_resposta AS (                                                                                                                                                                                                                                                                                                                                                                                                                                +
 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 c.tenant_id,                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 COUNT(DISTINCT c.id) AS conversas_afetadas,                                                                                                                                                                                                                                                                                                                                                                                                           +
 COUNT(*) FILTER (WHERE c.agent_enabled IS NOT FALSE) AS com_agente_ligado                                                                                                                                                                                                                                                                                                                                                                             +
 FROM public.conversas c                                                                                                                                                                                                                                                                                                                                                                                                                               +
 WHERE c.status IN ('ativa', 'humano')                                                                                                                                                                                                                                                                                                                                                                                                                 +
 AND c.agent_enabled IS NOT FALSE                                                                                                                                                                                                                                                                                                                                                                                                                      +
 AND EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT 1 FROM public.mensagens m                                                                                                                                                                                                                                                                                                                                                                                                                      +
 WHERE m.conversation_id = c.id                                                                                                                                                                                                                                                                                                                                                                                                                        +
 AND m.role = 'user'                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AND m.deleted_at IS NULL                                                                                                                                                                                                                                                                                                                                                                                                                              +
 AND m.created_at > now() - interval '30 minutes'                                                                                                                                                                                                                                                                                                                                                                                                      +
 )                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 AND NOT EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 SELECT 1 FROM public.mensagens m2                                                                                                                                                                                                                                                                                                                                                                                                                     +
 WHERE m2.conversation_id = c.id                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AND m2.role IN ('assistant','human')                                                                                                                                                                                                                                                                                                                                                                                                                  +
 AND m2.deleted_at IS NULL                                                                                                                                                                                                                                                                                                                                                                                                                             +
 AND m2.created_at > (SELECT MAX(m3.created_at) FROM public.mensagens m3 WHERE m3.conversation_id = c.id AND m3.role = 'user' AND m3.deleted_at IS NULL)                                                                                                                                                                                                                                                                                               +
 )                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 GROUP BY c.tenant_id                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 )                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 SELECT COALESCE(jsonb_agg(to_jsonb(s)), '[]'::jsonb)                                                                                                                                                                                                                                                                                                                                                                                                  +
 INTO v_leads_sem_resposta                                                                                                                                                                                                                                                                                                                                                                                                                             +
 FROM sem_resposta s;                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 IF jsonb_array_length(v_leads_sem_resposta) > 0 THEN                                                                                                                                                                                                                                                                                                                                                                                                  +
 v_alertas := v_alertas || jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                         +
 'tipo', 'leads_sem_resposta', 'severity', 'amarelo',                                                                                                                                                                                                                                                                                                                                                                                                  +
 'count', jsonb_array_length(v_leads_sem_resposta), 'detalhes', v_leads_sem_resposta                                                                                                                                                                                                                                                                                                                                                                   +
 );                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 RETURN v_alertas;                                                                                                                                                                                                                                                                                                                                                                                                                                     +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.obter_documentos_publicos_cliente(p_token uuid)                                                                                                                                                                                                                                                                                                                                                                     +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE v_lead_id uuid; v_result json;                                                                                                                                                                                                                                                                                                                                                                                                                +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 SELECT id INTO v_lead_id FROM public.leads WHERE chave_rastreamento = p_token LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                +
 IF v_lead_id IS NULL THEN RETURN '[]'::json; END IF;                                                                                                                                                                                                                                                                                                                                                                                                  +
 SELECT COALESCE(json_agg(json_build_object('id', d.id,'file_name', d.nome_arquivo,'label', d.rotulo,'file_path', d.caminho_arquivo,'file_type', d.tipo_arquivo,'created_at', d.created_at) ORDER BY d.created_at DESC), '[]'::json) INTO v_result                                                                                                                                                                                                     +
 FROM public.documentos_cliente d WHERE d.lead_id = v_lead_id;                                                                                                                                                                                                                                                                                                                                                                                         +
 RETURN v_result;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.obter_metricas_campanha(p_campaign_id uuid)                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                              +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE v_caller uuid := auth.uid(); v_tenant uuid; v_ativos integer; v_fechados integer; v_desistentes integer; v_repropostas integer; v_proximos jsonb;                                                                                                                                                                                                                                                                                             +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 IF v_caller IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;                                                                                                                                                                                                                                                                                                                                                                                   +
 SELECT tenant_id INTO v_tenant FROM public.campanhas WHERE id = p_campaign_id;                                                                                                                                                                                                                                                                                                                                                                        +
 IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;                                                                                                                                                                                                                                                                                                                                                                                         +
 IF NOT (v_tenant = v_caller OR EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_caller AND p.parent_user_id = v_tenant) OR public.is_platform_admin()) THEN                                                                                                                                                                                                                                                                                     +
 RAISE EXCEPTION 'forbidden';                                                                                                                                                                                                                                                                                                                                                                                                                          +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 SELECT COUNT(*) FILTER (WHERE state = 'ativo' AND archived_at IS NULL),                                                                                                                                                                                                                                                                                                                                                                               +
 COUNT(*) FILTER (WHERE state = 'fechado' AND archived_at IS NULL),                                                                                                                                                                                                                                                                                                                                                                                    +
 COUNT(*) FILTER (WHERE state = 'desistente' AND archived_at IS NULL),                                                                                                                                                                                                                                                                                                                                                                                 +
 COALESCE(SUM(reproposta_count), 0)                                                                                                                                                                                                                                                                                                                                                                                                                    +
 INTO v_ativos, v_fechados, v_desistentes, v_repropostas                                                                                                                                                                                                                                                                                                                                                                                               +
 FROM public.leads_campanha WHERE campaign_id = p_campaign_id;                                                                                                                                                                                                                                                                                                                                                                                         +
 SELECT COALESCE(jsonb_agg(rows ORDER BY rows->>'scheduled_at' ASC), '[]'::jsonb) INTO v_proximos                                                                                                                                                                                                                                                                                                                                                      +
 FROM (SELECT jsonb_build_object('id', sa.id, 'lead_id', sa.lead_id, 'action_type', sa.action_type, 'scheduled_at', sa.scheduled_at) AS rows                                                                                                                                                                                                                                                                                                           +
 FROM public.acoes_agendadas sa WHERE sa.lead_id IN (SELECT lead_id FROM public.leads_campanha WHERE campaign_id = p_campaign_id) AND sa.status IN ('pending','pendente') AND sa.action_type LIKE 'campaign%'                                                                                                                                                                                                                                          +
 ORDER BY sa.scheduled_at ASC LIMIT 10) t;                                                                                                                                                                                                                                                                                                                                                                                                             +
 RETURN jsonb_build_object('ativos', v_ativos, 'fechados', v_fechados, 'desistentes', v_desistentes, 'repropostas', v_repropostas, 'proximos_10', v_proximos);                                                                                                                                                                                                                                                                                         +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.obter_prompts_conversa(p_conversation_id uuid)                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS TABLE(message_id uuid, system_prompt text, user_message text, blocos_usados jsonb, trigger_disparado jsonb, rag_ativacao jsonb, turno_tipo text, fase_atual text, modelo text, bolhas_count integer, created_at timestamp with time zone)                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public', 'auth'                                                                                                                                                                                                                                                                                                                                                                                                                  +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 IF NOT EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT 1 FROM public.profiles                                                                                                                                                                                                                                                                                                                                                                                                                         +
 WHERE profiles.id = auth.uid() AND profiles.system_role = 'platform_admin'                                                                                                                                                                                                                                                                                                                                                                            +
 ) THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 RAISE EXCEPTION 'acesso restrito a platform_admin';                                                                                                                                                                                                                                                                                                                                                                                                   +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 SELECT mp.message_id, mp.system_prompt, mp.user_message,                                                                                                                                                                                                                                                                                                                                                                                              +
 mp.blocos_usados, mp.trigger_disparado, mp.rag_ativacao,                                                                                                                                                                                                                                                                                                                                                                                              +
 mp.turno_tipo, mp.fase_atual, mp.modelo, mp.bolhas_count, mp.created_at                                                                                                                                                                                                                                                                                                                                                                               +
 FROM public.prompts_mensagem mp                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WHERE mp.conversation_id = p_conversation_id                                                                                                                                                                                                                                                                                                                                                                                                          +
 ORDER BY mp.created_at ASC;                                                                                                                                                                                                                                                                                                                                                                                                                           +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.rifa_painel_agente(p_tenant_id uuid, p_rifa uuid DEFAULT NULL::uuid)                                                                                                                                                                                                                                                                                                                                                +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  STABLE SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                              +
  SET search_path TO ''                                                                                                                                                                                                                                                                                                                                                                                                                                +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_r public.rifas%rowtype;                                                                                                                                                                                                                                                                                                                                                                                                                           +
   v_min integer;                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   v_pagos integer;                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   v_reservados integer;                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_arrecadado bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                +
   v_a_receber bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   v_aguardando integer;                                                                                                                                                                                                                                                                                                                                                                                                                               +
   v_participantes integer;                                                                                                                                                                                                                                                                                                                                                                                                                            +
   v_top jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                        +
   v_fila jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   v_expirando jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   v_dividas_qtd integer;                                                                                                                                                                                                                                                                                                                                                                                                                              +
   v_dividas_total bigint;                                                                                                                                                                                                                                                                                                                                                                                                                             +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   PERFORM public.tenant_efetivo(p_tenant_id);                                                                                                                                                                                                                                                                                                                                                                                                         +
   if p_tenant_id is null then                                                                                                                                                                                                                                                                                                                                                                                                                         +
     return jsonb_build_object('ok', false, 'erro', 'sem_tenant');                                                                                                                                                                                                                                                                                                                                                                                     +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   if p_rifa is not null then                                                                                                                                                                                                                                                                                                                                                                                                                          +
     select * into v_r from public.rifas                                                                                                                                                                                                                                                                                                                                                                                                               +
     where id = p_rifa and tenant_id = p_tenant_id and deleted_at is null;                                                                                                                                                                                                                                                                                                                                                                             +
   else                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     select * into v_r from public.rifas                                                                                                                                                                                                                                                                                                                                                                                                               +
     where tenant_id = p_tenant_id and status = 'ativa' and deleted_at is null                                                                                                                                                                                                                                                                                                                                                                         +
     order by created_at desc limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                 +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   if not found then                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     return jsonb_build_object('ok', false, 'erro', 'rifa_nao_encontrada');                                                                                                                                                                                                                                                                                                                                                                            +
   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   v_min := case when v_r.numeracao_desde_zero then 0 else 1 end;                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select count(*) filter (where status = 'pago'),                                                                                                                                                                                                                                                                                                                                                                                                     +
          count(*) filter (where status = 'reservado')                                                                                                                                                                                                                                                                                                                                                                                                 +
     into v_pagos, v_reservados                                                                                                                                                                                                                                                                                                                                                                                                                        +
   from public.numeros_rifa where rifa_id = v_r.id;                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select coalesce(sum(valor_centavos) filter (where status = 'pago'), 0),                                                                                                                                                                                                                                                                                                                                                                             +
          coalesce(sum(valor_centavos) filter (where status in ('reservado', 'aguardando_validacao')), 0),                                                                                                                                                                                                                                                                                                                                             +
          count(*) filter (where status = 'aguardando_validacao'),                                                                                                                                                                                                                                                                                                                                                                                     +
          count(distinct coalesce(phone, 'nome:' || nome)) filter (where status = 'pago')                                                                                                                                                                                                                                                                                                                                                              +
     into v_arrecadado, v_a_receber, v_aguardando, v_participantes                                                                                                                                                                                                                                                                                                                                                                                     +
   from public.pedidos_rifa where rifa_id = v_r.id;                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select coalesce(jsonb_agg(jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                       +
            'pedido_id', id, 'nome', nome, 'phone', phone, 'numeros', numeros,                                                                                                                                                                                                                                                                                                                                                                         +
            'valor_centavos', valor_centavos, 'comprovante_url', comprovante_url,                                                                                                                                                                                                                                                                                                                                                                      +
            'criado_em', created_at) order by created_at), '[]'::jsonb)                                                                                                                                                                                                                                                                                                                                                                                +
     into v_fila                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   from (select * from public.pedidos_rifa                                                                                                                                                                                                                                                                                                                                                                                                             +
         where rifa_id = v_r.id and status = 'aguardando_validacao'                                                                                                                                                                                                                                                                                                                                                                                    +
         order by created_at limit 20) q;                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select coalesce(jsonb_agg(jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                       +
            'pedido_id', id, 'nome', nome, 'phone', phone, 'numeros', numeros,                                                                                                                                                                                                                                                                                                                                                                         +
            'valor_centavos', valor_centavos, 'expira_em', expira_em) order by expira_em), '[]'::jsonb)                                                                                                                                                                                                                                                                                                                                                +
     into v_expirando                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   from (select * from public.pedidos_rifa                                                                                                                                                                                                                                                                                                                                                                                                             +
         where rifa_id = v_r.id and status = 'reservado' and expira_em is not null                                                                                                                                                                                                                                                                                                                                                                     +
           and expira_em <= now() + interval '2 hours'                                                                                                                                                                                                                                                                                                                                                                                                 +
         order by expira_em limit 20) e;                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   -- FIX: usar LATERAL para resolver coluna não agrupada p.nome                                                                                                                                                                                                                                                                                                                                                                                       +
   select coalesce(jsonb_agg(t), '[]'::jsonb) into v_top from (                                                                                                                                                                                                                                                                                                                                                                                        +
     select                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       coalesce(latest.nome, max(p.nome)) as nome,                                                                                                                                                                                                                                                                                                                                                                                                     +
       p.phone,                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       sum(p.qtd_numeros) as numeros,                                                                                                                                                                                                                                                                                                                                                                                                                  +
       sum(p.valor_centavos) as gasto_centavos                                                                                                                                                                                                                                                                                                                                                                                                         +
     from public.pedidos_rifa p                                                                                                                                                                                                                                                                                                                                                                                                                        +
     left join lateral (                                                                                                                                                                                                                                                                                                                                                                                                                               +
       select p2.nome from public.pedidos_rifa p2                                                                                                                                                                                                                                                                                                                                                                                                      +
       where p2.rifa_id = v_r.id and p2.status = 'pago'                                                                                                                                                                                                                                                                                                                                                                                                +
         and coalesce(p2.phone, 'nome:' || p2.nome) = coalesce(p.phone, 'nome:' || p.nome)                                                                                                                                                                                                                                                                                                                                                             +
         and p2.nome !~* '^(lead|cliente whatsapp|cliente|contato)?$' and p2.nome !~ '^[0-9]{8,}$'                                                                                                                                                                                                                                                                                                                                                     +
       order by p2.created_at desc limit 1                                                                                                                                                                                                                                                                                                                                                                                                             +
     ) latest on true                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     where p.rifa_id = v_r.id and p.status = 'pago'                                                                                                                                                                                                                                                                                                                                                                                                    +
     group by coalesce(p.phone, 'nome:' || p.nome), p.phone, latest.nome                                                                                                                                                                                                                                                                                                                                                                               +
     order by sum(p.qtd_numeros) desc                                                                                                                                                                                                                                                                                                                                                                                                                  +
     limit 5                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select count(*), coalesce(sum(valor_centavos), 0)                                                                                                                                                                                                                                                                                                                                                                                                   +
     into v_dividas_qtd, v_dividas_total                                                                                                                                                                                                                                                                                                                                                                                                               +
   from public.rifa_dividas where tenant_id = p_tenant_id and pago = false;                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   return jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                          +
     'ok', true,                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     'rifa_id', v_r.id,                                                                                                                                                                                                                                                                                                                                                                                                                                +
     'titulo', v_r.titulo,                                                                                                                                                                                                                                                                                                                                                                                                                             +
     'status', v_r.status,                                                                                                                                                                                                                                                                                                                                                                                                                             +
     'numeracao_desde_zero', v_r.numeracao_desde_zero,                                                                                                                                                                                                                                                                                                                                                                                                 +
     'min', v_min,                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     'pagos', v_pagos,                                                                                                                                                                                                                                                                                                                                                                                                                                 +
     'reservados', v_reservados,                                                                                                                                                                                                                                                                                                                                                                                                                       +
     'arrecadado_centavos', v_arrecadado,                                                                                                                                                                                                                                                                                                                                                                                                              +
     'a_receber_centavos', v_a_receber,                                                                                                                                                                                                                                                                                                                                                                                                                +
     'aguardando_validacao', v_aguardando,                                                                                                                                                                                                                                                                                                                                                                                                             +
     'participantes_unicos', v_participantes,                                                                                                                                                                                                                                                                                                                                                                                                          +
     'top_compradores', v_top,                                                                                                                                                                                                                                                                                                                                                                                                                         +
     'fila_validacao', v_fila,                                                                                                                                                                                                                                                                                                                                                                                                                         +
     'expirando_soon', v_expirando,                                                                                                                                                                                                                                                                                                                                                                                                                    +
     'dividas_qtd', v_dividas_qtd,                                                                                                                                                                                                                                                                                                                                                                                                                     +
     'dividas_total_centavos', v_dividas_total                                                                                                                                                                                                                                                                                                                                                                                                         +
   );                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.solicitar_exclusao_conta()                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  SET search_path TO 'public'                                                                                                                                                                                                                                                                                                                                                                                                                          +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 v_user_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
 v_user_id := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                              +
 IF v_user_id IS NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                             +
 RAISE EXCEPTION 'Não autenticado';                                                                                                                                                                                                                                                                                                                                                                                                                    +
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 INSERT INTO public.activity_logs (user_id, action, entity_type, metadata)                                                                                                                                                                                                                                                                                                                                                                             +
 VALUES (v_user_id, 'lgpd_delete_request', 'user', jsonb_build_object('requested_at', now()));                                                                                                                                                                                                                                                                                                                                                         +
 UPDATE public.profiles SET deletion_requested_at = now() WHERE id = v_user_id;                                                                                                                                                                                                                                                                                                                                                                        +
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
